  return <section className="security-center panel" aria-labelledby="security-title"><div className="security-head"><div><p className="eyebrow">SECURITY GUARDIAN</p><h2 id="security-title">Keep every player protected.</h2><p className="muted">Review access events, payout safeguards and AI monitoring from one transparent security view.</p></div><button className="primary-btn" onClick={() => { setScanRunning(true); window.setTimeout(() => setScanRunning(false), 900); action(scanRunning ? 'Security scan already running' : 'Security scan complete: no new threats') }}><ShieldCheck size={16} /> {scanRunning ? 'Scanning...' : 'Run security scan'}</button></div><div className="security-overview"><div className="security-score"><div className="score-ring"><strong>98</strong><small>/100</small></div><div><p className="eyebrow">PROTECTION SCORE</p><h3>All systems secure</h3><span><span className="status-dot" /> Continuous monitoring active</span></div></div><div className="security-stats"><div><small>Blocked threats</small><b>24</b><span>this month</span></div><div><small>Protected payouts</small><b>187</b><span>reviewed by Boss</span></div><div><small>Open alerts</small><b>{alerts.filter((item) => !resolved.includes(item[0])).length}</b><span>needs attention</span></div></div></div><div className="security-events"><div className="panel-heading"><div><p className="eyebrow">AUDIT STREAM</p><h2>Recent security events</h2></div><button className="text-btn" onClick={() => action('Full audit log opened')}>View audit log <ArrowRight size={14} /></button></div>{alerts.map(([title, detail, tone]) => <div className={`security-event ${resolved.includes(title) ? 'resolved' : ''}`} key={title}><span className={`event-icon ${tone}`}><ShieldAlert size={15} /></span><div><b>{title}</b><small>{detail}</small></div>{resolved.includes(title) ? <span className="resolved-label"><Check size={13} /> Resolved</span> : <button className="outline-btn" onClick={() => { setResolved([...resolved, title]); action(`${title} marked as reviewed`) }}>Review</button>}</div>)}</div></section>
