function HealthHub({ active, action }: { active: string, action: (s: string) => void }) {
  const [urgency, setUrgency] = useState('Low concern')
  const [topic, setTopic] = useState('General guidance')
  const health = active === 'Health Assistant'
  const recovery = active === 'Recovery Support'
  const title = health ? 'Talk through your concern safely.' : recovery ? 'Support for the next step.' : 'Connect with a verified professional.'
  const description = health ? 'AI triage asks simple questions and gives general guidance. It does not diagnose or prescribe.' : recovery ? 'A private, non-judgmental space for goals, reminders and trusted referrals.' : 'Find doctors, nurses and counselors for human follow-up after a safe AI handoff.'
  return <section className="health-hub panel" aria-labelledby="health-hub-title"><div className="health-head"><div><p className="eyebrow">{health ? 'HEALTH SAFETY LAYER' : recovery ? 'RECOVERY SUPPORT' : 'PROFESSIONAL NETWORK'}</p><h2 id="health-hub-title">{title}</h2><p className="muted">{description}</p></div><span className="approval-lock"><ShieldCheck size={14} /> Human oversight active</span></div><div className="health-grid"><div className="health-card"><div className="health-icon"><HeartPulse size={20} /></div><h3>{health ? 'Start a guided check-in' : recovery ? 'Set a recovery goal' : 'Request a human referral'}</h3><p>{health ? 'Share only what you are comfortable sharing. Emergency symptoms should go directly to local emergency services.' : recovery ? 'Choose a focus and receive supportive steps without judgment.' : 'AI can prepare your summary, but a verified professional makes the next decision.'}</p><label>{health ? 'What do you need help with?' : recovery ? 'Choose a focus' : 'Preferred specialist'}<select value={topic} onChange={(event) => setTopic(event.target.value)}><option>General guidance</option><option>Stress and mental wellbeing</option><option>Substance recovery support</option><option>Physical health question</option></select></label><button className="primary-btn" onClick={() => action(`${active} check-in for ${topic} started`)}>{health ? 'Begin safe check-in' : recovery ? 'Create recovery plan' : 'Find a professional'} <ArrowRight size={15} /></button></div><div className="health-status"><div className="urgency-head"><div><p className="eyebrow">SAFETY STATUS</p><h3>{health ? 'Urgency guidance' : recovery ? 'Support plan status' : 'Referral safeguards'}</h3></div><span className={`urgency-pill ${urgency === 'Urgent / emergency' ? 'urgent' : urgency === 'Needs attention' ? 'attention' : ''}`}>{health ? urgency : 'Protected'}</span></div>{health && <div className="urgency-options">{['Low concern', 'Needs attention', 'Urgent / emergency'].map((item) => <button key={item} className={urgency === item ? 'selected' : ''} onClick={() => setUrgency(item)}>{item}<ChevronRight size={14} /></button>)}</div>}<div className="safety-note"><ShieldAlert size={16} /><p><b>{health && urgency === 'Urgent / emergency' ? 'Please seek emergency help now.' : 'AI is not a doctor.'}</b><small>{health && urgency === 'Urgent / emergency' ? 'Contact local emergency services or a nearby hospital. Do not wait for an AI response.' : 'No diagnosis, prescriptions or guaranteed outcomes. Your information stays separated from gaming data.'}</small></p></div><button className="outline-btn" onClick={() => action('Human oversight and referral policy opened')}>View safety policy <ArrowRight size={14} /></button></div></div></section>
}

