function PaymentHistory({ action }: { action: (s: string) => void }) {
  const [payments, setPayments] = useState<Array<{ id: string, amount: number, provider: string, reference: string, status: string, created_at: string }>>([])
  const [loaded, setLoaded] = useState(false)
  const [loading, setLoading] = useState(false)
  const load = async () => { setLoading(true); try { const response = await fetch('/api/payments/manual'); const data = await response.json(); if (!response.ok) throw new Error(data.error); setPayments(data.payments ?? []); setLoaded(true) } catch { action('Sign in to view manual payment history') } finally { setLoading(false) } }
  return <section className="panel payment-history" aria-labelledby="payment-history-title"><div className="panel-heading"><div><p className="eyebrow">MANUAL PAYMENT RECEIPTS</p><h2 id="payment-history-title">Payment history</h2></div><button className="outline-btn" onClick={() => void load()} disabled={loading}>{loading ? 'Loading…' : 'Refresh history'} <RefreshCw size={13} /></button></div>{!loaded ? <p className="muted">Your submitted receipts and Boss verification status will appear here.</p> : payments.length === 0 ? <p className="muted">No manual payment receipts found.</p> : <div className="payment-history-list">{payments.map((payment) => <div className="payment-history-row" key={payment.id}><div><b>{payment.provider} · {payment.reference}</b><small>{new Date(payment.created_at).toLocaleString()}</small></div><strong>TZS {Number(payment.amount).toLocaleString()}</strong><span className={`payment-status ${payment.status}`}>{payment.status}</span></div>)}</div>}</section>
}

