function CheckoutDialog({ items, onClose, onComplete }: { items: typeof products, onClose: () => void, onComplete: () => void }) {
  const [method, setMethod] = useState('M-Pesa')
  const [paymentMode, setPaymentMode] = useState<'manual' | 'azam'>('manual')
  const [phone, setPhone] = useState('')
  const [reference, setReference] = useState('')
  const [error, setError] = useState('')
  const [submitting, setSubmitting] = useState(false)
  const [submitted, setSubmitted] = useState(false)
  const total = items.reduce((sum, item) => sum + Number(item.price.replace(/[^0-9]/g, '')), 0)
  const submit = async () => {
  if (!/^\+?[0-9 ]{9,15}$/.test(phone.trim())) { setError('Enter a valid Tanzania mobile money number.'); return }
  if (paymentMode === 'manual' && !/^[A-Za-z0-9-]{6,80}$/.test(reference.trim())) { setError('Enter the payment reference from your mobile money receipt.'); return }
  setSubmitting(true); setError('')
  try {
  const endpoint = paymentMode === 'manual' ? '/api/payments/manual' : '/api/payments/azampay'
  const payload = paymentMode === 'manual' ? { amount: total, payerPhone: phone.replace(/\s/g, ''), provider: method, reference: reference.trim() } : { amount: total, accountNumber: phone.replace(/\s/g, ''), provider: method }
  const response = await fetch(endpoint, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) })
  const data = await response.json().catch(() => null)
  if (!response.ok) throw new Error(data?.error || 'Payment could not be started')
  setSubmitted(true)
    } catch (cause) { setError(cause instanceof Error ? cause.message : 'Payment could not be started') } finally { setSubmitting(false) }
  }
  return <div className="dialog-backdrop" role="presentation" onClick={onClose}><section className="checkout-dialog" role="dialog" aria-modal="true" aria-labelledby="checkout-title" onClick={(event) => event.stopPropagation()}>{submitted ? <div className="payment-success"><span className="success-icon"><Check size={24} /></span><p className="eyebrow">PAYMENT PROOF RECEIVED</p><h2 id="checkout-title">Order held for verification</h2><p>Your payment reference has been sent to Boss. Delivery will begin after the payment is verified.</p><div className="success-recipient"><b>0786095758 · Amina Mwinyi</b><small>Keep your mobile money receipt until the order is delivered.</small></div><button className="primary-btn" onClick={onClose}>Done</button></div> : <><div className="dialog-heading"><div><p className="eyebrow">NEXUS SECURE PAYMENT</p><h2 id="checkout-title">Complete your order</h2><p className="muted">Your digital delivery stays in escrow until payment is confirmed.</p></div><button className="icon-btn" aria-label="Close checkout" onClick={onClose}><X size={18} /></button></div>
    <div className="checkout-summary"><div><span>{items.length} {items.length === 1 ? 'item' : 'items'}</span><strong>TZS {total.toLocaleString()}</strong></div><span className="escrow-label"><ShieldCheck size={14} /> Escrow protected</span></div>
  <div className="payment-mode-tabs" role="tablist" aria-label="Payment route"><button className={paymentMode === 'manual' ? 'active' : ''} onClick={() => setPaymentMode('manual')}>Manual payment</button><button className={paymentMode === 'azam' ? 'active' : ''} onClick={() => setPaymentMode('azam')}>AzamPay prompt</button></div>
  {paymentMode === 'manual' && <div className="manual-payment-note"><CreditCard size={16} /><div><b>Send payment to {`0786095758`}</b><small>{`Account name: Amina Mwinyi`} · Boss verifies before delivery.</small></div></div>}
  <div className="payment-methods" role="radiogroup" aria-label="Payment method">{['M-Pesa', 'Airtel Money', 'Tigo Pesa'].map((item) => <button key={item} className={method === item ? 'method selected' : 'method'} role="radio" aria-checked={method === item} onClick={() => setMethod(item)}><span className="method-mark"><CircleDollarSign size={15} /></span><span>{item}</span><span className="method-check">{method === item ? '✓' : ''}</span></button>)}</div>
  <label className="phone-field">{paymentMode === 'manual' ? 'Your mobile money number' : 'Mobile money number'}<input inputMode="tel" value={phone} onChange={(event) => { setPhone(event.target.value); setError('') }} placeholder="e.g. 0712 345 678" /></label>
  {paymentMode === 'manual' && <label className="phone-field">Payment reference<input value={reference} onChange={(event) => { setReference(event.target.value.toUpperCase()); setError('') }} placeholder="e.g. MPESA123456" /></label>}
  {error && <p className="form-error" role="alert">{error}</p>}
  <div className="dialog-actions"><button className="ghost-btn" onClick={onClose} disabled={submitting}>Cancel</button><button className="primary-btn" onClick={submit} disabled={submitting}><LockKeyhole size={15} /> {submitting ? 'Submitting…' : paymentMode === 'manual' ? 'Submit payment proof' : `Pay with ${method}`}</button></div>
  </>}</section></div>
}

