function AdminPaymentHistory() {
  const [payments, setPayments] = useState<Array<{ id: string; amount: number; provider: string; reference: string; status: string; created_at: string }>>([])
  useEffect(() => { void fetch('/api/admin/manual-payments/history').then((response) => response.ok ? response.json() : { payments: [] }).then((data) => setPayments(data.payments ?? [])) }, [])
  return <section className="payment-history panel"><div className="section-head"><div><p className="eyebrow">PAYMENT LEDGER</p><h2>Complete payment history</h2></div><span className="count-pill">{payments.length} records</span></div><div className="payment-table"><div className="payment-table-head"><span>Reference</span><span>Provider</span><span>Amount</span><span>Status</span><span>Date</span></div>{payments.map((payment) => <div className="payment-table-row" key={payment.id}><b>{payment.reference}</b><span>{payment.provider}</span><strong>TZS {Number(payment.amount).toLocaleString()}</strong><span className={`history-status ${payment.status}`}>{payment.status}</span><time>{new Date(payment.created_at).toLocaleDateString()}</time></div>)}{payments.length === 0 && <div className="approval-empty">No payment history available.</div>}</div></section>
}

function ApprovalDock({ action }: { action: (s: string) => void }) {
  const [items, setItems] = useState<Array<{ id: string, amount: number, provider: string, reference: string, payer_phone: string, created_at: string }>>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const loadQueue = async () => { setLoading(true); try { const response = await fetch('/api/admin/manual-payments'); const data = await response.json(); if (!response.ok) throw new Error(data.error); setItems(data.payments ?? []); setError('') } catch { setError('Sign in as an administrator to load manual payment proofs.') } finally { setLoading(false) } }
  useEffect(() => { void loadQueue() }, [])
  const decide = async (item: typeof items[number], status: 'verified' | 'rejected') => { try { const response = await fetch('/api/admin/manual-payments', { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ id: item.id, status }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error); setItems((current) => current.filter((entry) => entry.id !== item.id)); action(`Manual payment ${item.reference} ${status} by Boss`) } catch { action(`Could not ${status} manual payment ${item.reference}`) } }
  return <section className="approval-dock panel" aria-labelledby="approval-dock-title"><div className="approval-head"><div><p className="eyebrow">BOSS APPROVAL REQUIRED</p><h2 id="approval-dock-title">Manual payment proofs</h2><p className="approval-summary">Verify money received at 0786095758 · Amina Mwinyi before fulfillment.</p></div><div className="approval-head-actions"><span className="count-pill">{loading ? '...' : `${items.length} pending`}</span><button className="text-btn" onClick={() => void loadQueue}>Refresh</button></div></div>{error ? <div className="approval-empty"><ShieldAlert size={17} /> {error}</div> : loading ? <div className="approval-empty">Loading payment proofs...</div> : items.length === 0 ? <div className="approval-empty"><Check size={17} /> No pending manual payment proofs.</div> : <div className="approval-list">{items.map((item) => <div className="approval-item" key={item.id}><div><b>{item.provider} · TZS {Number(item.amount).toLocaleString()}</b><small>Ref {item.reference} · From {item.payer_phone} · {new Date(item.created_at).toLocaleString()}</small></div><div className="approval-actions"><button className="reject-btn" onClick={() => void decide(item, 'rejected')}>Reject</button><button className="approve-btn" onClick={() => void decide(item, 'verified')}>Verify payment</button></div></div>)}</div>}</section>
}

function TournamentDialog({ title, onClose, onRegister }: { title: string, onClose: () => void, onRegister: () => void }) {
  const [gamertag, setGamertag] = useState('')
  const [error, setError] = useState('')
  const submit = () => {
    if (!gamertag.trim()) { setError('Enter your eFootball gamertag to continue.'); return }
    onRegister()
  }
  return <div className="dialog-backdrop" role="presentation" onClick={onClose}><section className="create-dialog tournament-dialog" role="dialog" aria-modal="true" aria-labelledby="tournament-dialog-title" onClick={(event) => event.stopPropagation()}>
    <div className="dialog-heading"><div><p className="eyebrow">TOURNAMENT REGISTRATION</p><h2 id="tournament-dialog-title">Join {title}</h2><p className="muted">Your entry will be held in escrow until the league is confirmed by Boss.</p></div><button className="icon-btn" aria-label="Close registration" onClick={onClose}><X size={18} /></button></div>
    <div className="registration-note"><Trophy size={17} /><div><b>Fair play protected</b><small>Match settlement and payouts are reviewed automatically.</small></div></div>
    <label>eFootball gamertag<input autoFocus value={gamertag} onChange={(event) => { setGamertag(event.target.value); setError('') }} placeholder="e.g. Nexus_Champion" /></label>
    {error && <p className="form-error" role="alert">{error}</p>}
    <div className="dialog-actions"><button className="ghost-btn" onClick={onClose}>Cancel</button><button className="primary-btn" onClick={submit}><Trophy size={15} /> Send registration</button></div>
  </section></div>
}

function CreateDialog({ title, onClose, onCreate }: { title: string, onClose: () => void, onCreate: () => void }) {
  const [name, setName] = useState('')
  const [description, setDescription] = useState('')
  const [error, setError] = useState('')
  const submit = () => {
    if (!name.trim()) { setError('Add a title before saving this record.'); return }
    if (!description.trim()) { setError('Add a short description so the approval queue has context.'); return }
    onCreate()
  }
  return <div className="dialog-backdrop" role="presentation" onClick={onClose}><section className="create-dialog" role="dialog" aria-modal="true" aria-labelledby="create-dialog-title" onClick={(event) => event.stopPropagation()}>
    <div className="dialog-heading"><div><p className="eyebrow">BOSS APPROVAL FLOW</p><h2 id="create-dialog-title">{title}</h2><p className="muted">Prepare the details first. Sensitive actions remain locked until Boss approval.</p></div><button className="icon-btn" aria-label="Close dialog" onClick={onClose}><X size={18} /></button></div>
    <label>Title or name<input autoFocus value={name} onChange={(event) => { setName(event.target.value); setError('') }} placeholder="e.g. Nexus Weekend League" /></label>
    <label>Short description<textarea rows={3} value={description} onChange={(event) => { setDescription(event.target.value); setError('') }} placeholder="Add the key details for this record..." /></label>
    {error && <p className="form-error" role="alert">{error}</p>}
    <div className="dialog-actions"><button className="ghost-btn" onClick={onClose}>Cancel</button><button className="primary-btn" onClick={submit}><Check size={16} /> Save for approval</button></div>
  </section></div>
}
